# owner: platform
"""Short absence notices to send home to parents."""

from typing import Iterable, List
from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed
from datetime import date

def format_day(when: date) -> str:
    """Spell a day out the way a parent would read it."""
    return f"{when:%B} {when.day}, {when.year}"

def check_marks(
    student: Student, marks: List[Mark]
) -> None:
    """Refuse marks that were written for somebody else."""
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for {mark.student_id!r} is not for "
                f"{student.student_id!r}"
            )

def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Notice listing the days a student was absent."""
    all_marks = list(marks)
    check_marks(student, all_marks)
    days = sorted(set(days_missed(all_marks)))
    if not days:
        raise ValueError(
            f"no absences for {student.student_id!r}"
        )
    count = len(days)
    noun = "day" if count == 1 else "days"
    dates = "; ".join(format_day(when) for when in days)
    name = f"{student.first_name} {student.last_name}"
    return (
        "Dear parent or guardian,\n\n"
        f"{name} missed {count} {noun}: {dates}.\n\n"
        "Please contact the school if you have "
        "questions about these absences."
    )
